"use client";

import { Spinner } from "@chakra-ui/react"

export const SpinnerBasic = () => {
  return <Spinner size="sm" />
}

"use client";

import { Spinner } from "@chakra-ui/react"

export const SpinnerCustomColor = () => {
  return <Spinner color="teal.500" size="lg" />
}

"use client";

import { For, Spinner, useRecipe } from "@chakra-ui/react"

export const SpinnerSizeTable = () => {
  const recipe = useRecipe({ key: "spinner" })
  return (
    <div>
      <For each={recipe.variantMap.size}>
        {(size) => (
          <Spinner key={size} margin={3} color="green.500" size={size} />
        )}
      </For>
    </div>
  )
}

"use client";

import { Spinner, Stack } from "@chakra-ui/react"
import { colorPalettes } from "@/components/rendyn-libraries/chakra/upstream/lib/color-palettes"

export const SpinnerWithColors = () => {
  return (
    <Stack gap="2" align="flex-start">
      {colorPalettes.map((colorPalette) => (
        <Stack
          align="center"
          key={colorPalette}
          direction="row"
          gap="10"
          px="4"
        >
          <Spinner
            size="sm"
            color="colorPalette.600"
            colorPalette={colorPalette}
          />
          <Spinner
            size="md"
            color="colorPalette.600"
            colorPalette={colorPalette}
          />
          <Spinner
            size="lg"
            color="colorPalette.600"
            colorPalette={colorPalette}
          />
        </Stack>
      ))}
    </Stack>
  )
}

"use client";

import { Spinner } from "@chakra-ui/react"
import { LuLoader } from "react-icons/lu"

export const SpinnerWithCustomIndicator = () => (
  <Spinner asChild borderWidth="0">
